/**
 * helpers.tsx — single source of FPS/dimension/easing utilities.
 *
 * INSTALL: copy this file to your project as `src/helpers.tsx` next to `src/cues.json`.
 * The relative import below assumes that layout:
 *
 *   proj/
 *   ├── src/
 *   │   ├── helpers.tsx   ← this file
 *   │   ├── cues.json     ← generated by make_cues.py
 *   │   ├── Root.tsx
 *   │   └── Main.tsx
 *
 * All timing values passed to these helpers come from cue events (seconds) —
 * never hardcode new timing in components. See SKILL.md Phase 4.4.
 */
import {Easing, interpolate, spring, useCurrentFrame} from 'remotion';
import cues from './cues.json';

// Single source of configuration: cues.json. Don't hardcode FPS/dimensions anywhere else.
export const FPS = cues.fps;
export const W = cues.width;
export const H = cues.height;
export const totalFrames = Math.ceil(cues.dur * FPS);

/** seconds → frames (rounded to nearest). All component timing goes through this. */
export const fr = (seconds: number) => Math.round(seconds * FPS);

/** ease-in-out cubic between two times (seconds, from cues.json), clamped. */
export const ease = (
  frame: number,
  startSeconds: number,
  endSeconds: number,
  from = 0,
  to = 1,
) =>
  interpolate(frame, [fr(startSeconds), fr(endSeconds)], [from, to], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

/** spring with a delay (seconds), safe against negative frames. */
export const spr = (frame: number, delaySeconds = 0) =>
  spring({
    frame: Math.max(0, frame - fr(delaySeconds)),
    fps: FPS,
    config: {damping: 13, stiffness: 170, mass: 0.8},
  });

/** sinusoidal ambient motion based on seconds (not frames) — deterministic. */
export const breathe = (frame: number, amplitude = 0.02, periodSeconds = 2.4) =>
  1 + amplitude * Math.sin((frame / FPS) * ((Math.PI * 2) / periodSeconds));

/** decaying screen shake: used for a few frames after an impact (seconds). */
export const shake = (frame: number, impactSeconds: number, seconds = 0.3) => {
  const t = frame / FPS - impactSeconds;
  if (t < 0 || t > seconds) return {x: 0, y: 0};
  const decay = 1 - t / seconds;
  const seedA = Math.sin(frame * 12.9898) * 43758.5453;
  const seedB = Math.sin(frame * 78.233) * 12345.6789;
  return {
    x: (seedA - Math.floor(seedA) - 0.5) * 24 * decay,
    y: (seedB - Math.floor(seedB) - 0.5) * 24 * decay,
  };
};

/** scene window from cues.json — the ONLY way components should learn scene timing. */
export const scene = (id: string) => {
  const s = cues.scenes.find((s: any) => s.id === id);
  if (!s) throw new Error(`scene "${id}" not found in cues.json`);
  return s;
};

/** seconds → start frame for a cue, e.g. <Sequence from={cueAt(1.2)}> */
export const cueAt = (seconds: number) => fr(seconds);

/**
 * Convert cue-event ABSOLUTE seconds to SECONDS-INSIDE-THIS-SEQUENCE.
 * useCurrentFrame() inside <Sequence from={cueAt(s.start)}> is local (0 at the
 * scene boundary), but cues.json times are absolute — mixing them is the most
 * common motion-craft bug (bars never fill, entrances never play).
 * Usage inside a scene component:
 *   const t = useSceneClock('s2-evidence');   // local frame → absolute seconds
 *   const a = easeAt(t, cue.t, cue.t + cue.duration);
 */
export const useSceneClock = (id: string) => {
  const frame = useCurrentFrame();
  return frame / FPS + scene(id).start;
};

/** ease variant taking ABSOLUTE seconds (pair with useSceneClock). */
export const easeAt = (
  absSeconds: number,
  startSeconds: number,
  endSeconds: number,
  from = 0,
  to = 1,
) =>
  interpolate(
    fr(absSeconds),
    [fr(startSeconds), fr(endSeconds)],
    [from, to],
    {easing: Easing.inOut(Easing.cubic), extrapolateLeft: 'clamp', extrapolateRight: 'clamp'},
  );
